/**
 * Open market — docs/TOKEN_ROUNDS.md §3.1, §6.
 *
 * The market is the DEMAND side of the IRL economy. Only IRL actions mint
 * scarce goods, so the market is what makes the physical game worth doing:
 * "Someone is bidding 40 credits for your location badge. Accept?" fires
 * whenever a motivated human is online, generated by people who never left
 * their desks.
 *
 * If this link does not exist, the always-on layer becomes the thing people
 * check INSTEAD of playing — which is exactly how v2 lost its players.
 *
 * Pure logic only: validation, escrow arithmetic, and expiry. Persistence
 * lives in the route module.
 */

import { canAfford, summarizeLedger } from "./creditLedger.js";

/** A listing that lives longer than this stops being urgent. */
export const DEFAULT_LISTING_TTL_MS = 6 * 60 * 60_000; // 6 hours

/** Hard ceiling so a listing cannot sit open across a whole sprint. */
export const MAX_LISTING_TTL_MS = 24 * 60 * 60_000;

/**
 * Validate a proposed listing.
 *
 * @param {object} input
 * @param {string} input.seller
 * @param {number} input.price
 * @param {string} input.itemKind
 * @param {string} input.regionId
 * @param {string|number} [input.now]
 * @param {number} [input.ttlMs]
 * @param {Array<object>} [ledger] - entries, to check the seller can cover it
 * @returns {{ok:boolean, reason:string|null, expiresAt:Date|null}}
 */
export function validateListing(input = {}) {
  const {
    seller,
    price,
    itemKind,
    regionId,
    now = Date.now(),
    ttlMs = DEFAULT_LISTING_TTL_MS,
    ledger,
  } = input;

  const fail = (reason) => ({ ok: false, reason, expiresAt: null });

  if (!seller || typeof seller !== "string") return fail("missing_seller");
  if (!itemKind || typeof itemKind !== "string") return fail("missing_item_kind");
  if (!regionId || typeof regionId !== "string") return fail("missing_region");

  const cost = Math.floor(Number(price));
  if (!Number.isFinite(cost) || cost <= 0) return fail("invalid_price");

  const ttl = Math.floor(Number(ttlMs));
  if (!Number.isFinite(ttl) || ttl <= 0) return fail("invalid_ttl");
  if (ttl > MAX_LISTING_TTL_MS) return fail("ttl_too_long");

  const nowMs = typeof now === "number" ? now : Date.parse(now);
  if (!Number.isFinite(nowMs)) return fail("invalid_now");

  // Only spend against a known balance when the caller supplied the ledger;
  // escrow is checked again at fill time.
  if (Array.isArray(ledger)) {
    const affordable = canAfford(ledger, seller, cost);
    if (!affordable.ok) return fail(affordable.reason);
  }

  return { ok: true, reason: null, expiresAt: new Date(nowMs + ttl) };
}

/**
 * Attempt to fill an open listing, escrowing BOTH sides.
 *
 * Returns the signed ledger entries to write. The caller must apply them in
 * one transaction — credits leaving the seller and arriving at the buyer
 * must never be able to partially commit.
 *
 * @param {object} input
 * @param {{id:number, seller:string, price:number, status:string, expires_at:string|Date}} input.listing
 * @param {string} input.buyer
 * @param {Array<object>} input.ledger
 * @param {string|number} [input.now]
 * @returns {{ok:boolean, reason:string|null, entries:Array<object>}}
 */
export function fillListing(input = {}) {
  const { listing, buyer, ledger = [], now = Date.now() } = input;
  const fail = (reason) => ({ ok: false, reason, entries: [] });

  if (!listing || typeof listing.id !== "number") return fail("missing_listing");
  if (!buyer || typeof buyer !== "string") return fail("missing_buyer");

  const buyerLower = buyer.toLowerCase();
  const sellerLower = String(listing.seller || "").toLowerCase();

  if (listing.status && listing.status !== "open") return fail("listing_not_open");
  if (sellerLower === buyerLower) return fail("self_fill");

  const nowMs = typeof now === "number" ? now : Date.parse(now);
  const expMs = listing.expires_at ? Date.parse(listing.expires_at) : NaN;
  if (Number.isFinite(expMs) && nowMs > expMs) return fail("listing_expired");

  const price = Math.floor(Number(listing.price));
  if (!Number.isFinite(price) || price <= 0) return fail("invalid_price");

  // Buyer must be able to pay; seller must be able to deliver. Both sides
  // are escrowed in the same breath, so neither can front-run the other.
  const buyerBalance = summarizeLedger(ledger, buyerLower).balance;
  if (buyerBalance < price) return fail("insufficient_credits");

  const sellerBalance = summarizeLedger(ledger, sellerLower).balance;
  if (sellerBalance < price) return fail("seller_cannot_deliver");

  const ref = String(listing.id);
  // Two entries, not three: the buyer's payment goes straight to the seller.
  // A debit + credit pair for the same money would net to a 5-credit hole in
  // the economy — credits must move, never be created or destroyed.
  return {
    ok: true,
    reason: null,
    entries: [
      { address: buyerLower, amount: -price, reason: "market_spend", ref },
      { address: sellerLower, amount: price, reason: "market_payout", ref },
    ],
  };
}

/**
 * Refund a listing that expired or was cancelled.
 * The seller's escrowed credits go back; nothing is minted.
 *
 * @param {{seller:string, price:number}} listing
 * @returns {Array<object>} signed ledger entries
 */
export function refundListing(listing = {}) {
  const price = Math.floor(Number(listing.price));
  const seller = String(listing.seller || "").toLowerCase();
  if (!seller || !Number.isFinite(price) || price <= 0) return [];
  return [{
    address: seller,
    amount: price,
    reason: "market_refund",
    ref: listing.id == null ? null : String(listing.id),
  }];
}

/**
 * Sweep expired listings. Pure: returns which ids are now expired so the
 * caller can flip status and refund in a transaction.
 *
 * @param {Array<{id:number, status:string, expires_at:string|Date}>} listings
 * @param {string|number} [now]
 * @returns {Array<{id:number, seller:string, price:number}>}
 */
export function expireListing(listings, now = Date.now()) {
  const nowMs = typeof now === "number" ? now : Date.parse(now);
  if (!Number.isFinite(nowMs)) return [];

  return (listings || [])
    .filter((l) => l && l.status === "open")
    .filter((l) => {
      const exp = l.expires_at ? Date.parse(l.expires_at) : NaN;
      return Number.isFinite(exp) && nowMs > exp;
    })
    .map((l) => ({
      id: l.id,
      seller: String(l.seller || "").toLowerCase(),
      price: Math.floor(Number(l.price) || 0),
    }));
}

export default {
  DEFAULT_LISTING_TTL_MS,
  MAX_LISTING_TTL_MS,
  validateListing,
  fillListing,
  refundListing,
  expireListing,
};